// Define the state structure for the bit generator
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BitGeneratorState {
    pub seed: Option<u64>,
    pub state: u64,
}

/// Computes an internal 64‐bit state from an optional seed.
/// - If `seed` is `None`, returns 0.
/// - If `seed` is `Some(s)`, returns `s | 1`, which is guaranteed non‐zero.
pub fn compute_internal_state(seed: Option<u64>) -> u64 {
    match seed {
        Some(s) => s | 1,
        None    => 0,
    }
}

/// Initializes a NumPy‐style random bit generator state:
/// - `seed` field is exactly the input `seed`.
/// - `state` is 0 when `seed` is `None`, otherwise a non‐zero value computed from `seed`.
pub fn numpy_random_bit_generator(seed: Option<u64>) -> BitGeneratorState {
    let state = compute_internal_state(seed);
    BitGeneratorState { seed, state }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_no_seed() {
        let s = numpy_random_bit_generator(None);
        assert_eq!(s.seed, None);
        assert_eq!(s.state, 0);
    }

    #[test]
    fn test_some_seed_nonzero() {
        let seeds = [0u64, 1, 42, u64::MAX];
        for &seed in &seeds {
            let s = numpy_random_bit_generator(Some(seed));
            assert_eq!(s.seed, Some(seed));
            assert_ne!(s.state, 0, "internal state must be non-zero for seed={}", seed);
        }
    }

    #[test]
    fn test_compute_internal_state_varies() {
        // ensure compute_internal_state(Some(x)) = x|1
        for &x in &[0u64, 2, 0xFFFF_FFFF_FFFF_FFFE, u64::MAX] {
            let got = compute_internal_state(Some(x));
            assert_eq!(got, x | 1);
        }
        assert_eq!(compute_internal_state(None), 0);
    }
}